    [3446]={name="Darkwood Staff",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt' - pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
    [3488]={name="Copper Battle Axe",quality=2,ilvl=13,reqLevel=8,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [3511]={name="Cloak of the People's Militia",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Red Leather Bandanas' - pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [3578]={name="Harvester's Pants",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Killing Fields' - pick it over the other choices. In Westfall.",zone="Westfall",questName="The Killing Fields",lore="Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"},
