    [5257]={name="Dark Hooded Cape",quality=3,ilvl=37,reqLevel=32,sourceType="world_drop",instructions="Drops from Nimar the Slayer (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Nimar the Slayer"},
    [5279]={name="Harpy Skinner",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Serena Bloodfeather' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Serena Bloodfeather",lore="You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."},
    [5314]={name="Boar Hunter's Cape",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Consumed by Hatred' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Consumed by Hatred",lore="Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."},
    [5319]={name="Bashing Pauldrons",quality=1,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="Drops from Haren Swifthoof (rare elite) in The Loch.",zone="The Loch",npc="Haren Swifthoof"},
    [5327]={name="Greasy Tinker's Pants",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'The Escape' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="The Escape",lore="I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"},
    [5346]={name="Orcish Battle Bow",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'Centaur Bracers' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Centaur Bracers",lore="The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'. In The Barrens.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5355]={name="Beastmaster's Girdle",quality=2,ilvl=28,sourceType="quest_reward",instructions="Reward from the quest 'Isha Awak'. In The Barrens.",zone="The Barrens",questName="Isha Awak",lore="The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."},
    [5394]={name="Archery Training Gloves",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Balance of Nature' - pick it over the other choices. In Shadowglen.",zone="Shadowglen",questName="The Balance of Nature",lore="Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."},
    [5404]={name="Serpent's Shoulders",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Lady Anacondra in Wailing Caverns.",zone="Wailing Caverns",npc="Lady Anacondra"},
    [5423]={name="Boahn's Fang",quality=3,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="Drops from Boahn (rare spawn) in Wailing Caverns.",zone="Wailing Caverns",npc="Boahn"},
    [5581]={name="Smooth Walking Staff",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Stolen Journal' - pick it over the other choices. In Coldridge Valley.",zone="Coldridge Valley",questName="The Stolen Journal",lore="My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."},
    [5591]={name="Rain-spotted Cape",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'The Enchanted Glade' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Enchanted Glade",lore="I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."},
    [5596]={name="Ashwood Bow",quality=1,ilvl=11,sourceType="quest_reward",instructions="Reward from the quest 'Crown of the Earth' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Crown of the Earth",lore="Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."},
    [5611]={name="Tear of Grief",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'For Love Eternal'. In Darkshore.",zone="Darkshore",questName="For Love Eternal",lore="In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."},
    [5617]={name="Vagabond Leggings",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Bashal'Aran' - pick it over the other choices. In Darkshore.",zone="Darkshore",questName="Bashal'Aran",lore="It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."},
    [5749]={name="Scythe Axe",quality=2,ilvl=23,reqLevel=18,sourceType="world_drop",instructions="Drops from Ma'ruk Wyrmscale (rare spawn) in Dun Algaz.",zone="Dun Algaz",npc="Ma'ruk Wyrmscale"},
    [5754]={name="Wolfpack Medallion",quality=2,ilvl=31,reqLevel=26,sourceType="world_drop",instructions="Drops from Terrowulf Packlord (rare spawn) in Kalimdor.",zone="Kalimdor",npc="Terrowulf Packlord"},
    [5777]={name="Brave's Axe",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Rite of Strength' - pick it over the other choices. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="Rite of Strength",lore="The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."},
    [5781]={name="Murloc Scale Breastplate",quality=2,ilvl=19,reqLevel=14,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5957]={name="Handstitched Leather Vest",quality=1,ilvl=8,reqLevel=3,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5961]={name="Dark Leather Pants",quality=2,ilvl=23,reqLevel=18,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [6059]={name="Nomadic Vest",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'The Battleboars'. In Red Cloud Mesa.",zone="Red Cloud Mesa",questName="The Battleboars",lore="The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."},
    [6070]={name="Wolfskin Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Wolves Across the Border' - pick it over the other choices. In Northshire Valley.",zone="Northshire Valley",questName="Wolves Across the Border",lore="I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."},
    [6094]={name="Piercing Axe",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Red Silk Bandanas' - pick it over the other choices. In The Deadmines.",zone="The Deadmines",questName="Red Silk Bandanas",lore="It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank."},
    [6179]={name="Privateer's Cape",quality=2,ilvl=19,reqLevel=14,sourceType="world_drop",instructions="Drops from Brack (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Brack"},
    [6198]={name="Jurassic Wristguards",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="Drops from Razormaw Matriarch (rare spawn) in Eastern Kingdoms.",zone="Eastern Kingdoms",npc="Razormaw Matriarch"},
    [6215]={name="Balanced Fighting Stick",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Wanted:  \"Hogger\"' - pick it over the other choices. In Elwynn Forest.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6340]={name="Fenrus' Hide",quality=3,ilvl=26,reqLevel=20,sourceType="boss_drop",instructions="Drops from Fenrus the Devourer in Shadowfang Keep.",zone="Shadowfang Keep",npc="Fenrus the Devourer"},
